import { describe, it, expect } from 'vitest';
import { ReplicateMediaAdapter } from '../media.adapter';
import { metadata } from '../metadata';

// metadata.ts is regenerated by tools/codegen/snapshot-replicate-catalog.mjs.
// The defaults resolver only offers Replicate for categories listed here, so a
// regeneration that drops one silently disables the feature (#221 dropped
// `image-outpaint`, breaking the Designer's Expand Image).
describe('replicate metadata', () => {
  it('declares image-outpaint with flux-fill-pro while the adapter supports outpaint', () => {
    const adapter = new ReplicateMediaAdapter({} as any);
    expect(adapter.capabilities.outpaint).toBe(true);
    expect(metadata.mediaCategories).toContain('image-outpaint');
    expect(
      (metadata.mediaModels as Record<string, { id: string }[]>)['image-outpaint'].map((m) => m.id),
    ).toContain('black-forest-labs/flux-fill-pro');
  });

  it('replaces the retired google/veo-3 with google/veo-3.1 in text-to-video', () => {
    // veo-3 was retired upstream (prod 404s); the snapshot must track the live
    // catalog or the studio offers a model that always fails.
    const t2v = (metadata.mediaModels as Record<string, { id: string; fields: { name: string }[] }[]>)[
      'text-to-video'
    ];
    expect(t2v.map((m) => m.id)).toContain('google/veo-3.1');
    expect(t2v.map((m) => m.id)).not.toContain('google/veo-3');
    // veo-3.1 adds generate_audio over veo-3 (verified against the live schema).
    const veo = t2v.find((m) => m.id === 'google/veo-3.1')!;
    expect(veo.fields.map((f) => f.name)).toContain('generate_audio');
  });

  it('declares Veo in both video categories with the 4/6/8 duration contract', () => {
    const models = metadata.mediaModels as Record<
      string,
      { id: string; fields: { name: string; type?: string; default?: unknown; options?: { value: string }[] }[] }[]
    >;
    for (const category of ['text-to-video', 'image-to-video']) {
      const veo = models[category].find((model) => model.id === 'google/veo-3.1')!;
      expect(veo).toBeDefined();
      const duration = veo.fields.find((field) => field.name === 'duration')!;
      expect(duration.type).toBe('select');
      expect(duration.options?.map((option) => option.value)).toEqual(['4', '6', '8']);
      expect(duration.default).toBe('8');
    }
  });

  it('keeps Seedance and Kling at 5/10 seconds and Video-01 without a duration input', () => {
    const models = metadata.mediaModels as Record<
      string,
      { id: string; fields: { name: string; type?: string; default?: unknown; options?: { value: string }[] }[] }[]
    >;
    for (const category of ['text-to-video', 'image-to-video']) {
      for (const id of ['bytedance/seedance-1-pro', 'kwaivgi/kling-v2.5-turbo-pro']) {
        const duration = models[category]
          .find((model) => model.id === id)!
          .fields.find((field) => field.name === 'duration')!;
        expect(duration.type).toBe('select');
        expect(duration.options?.map((option) => option.value)).toEqual(['5', '10']);
        expect(duration.default).toBe('5');
      }
      const video01 = models[category].find((model) => model.id === 'minimax/video-01')!;
      expect(video01.fields.some((field) => field.name === 'duration')).toBe(false);
    }
  });
});
